-- The attack lab on a judge's own unit (POST /api/units/:id/attack-prep): each one-member change it made, so the
-- result screen can show the subtraction a typical n>=3 tool would allow. The figure is a SYNTHETIC colleague's sample
-- pay, generated by the server; no real member's figure is ever stored. Additive: a new table only.
CREATE TABLE IF NOT EXISTS unit_attacks (
  unit_id INTEGER NOT NULL,
  started_at INTEGER NOT NULL,
  account_id TEXT NOT NULL,
  release_id INTEGER NOT NULL,
  query TEXT NOT NULL,
  cell TEXT NOT NULL,
  action TEXT NOT NULL,
  public_key TEXT NOT NULL,
  grade TEXT NOT NULL,
  gender TEXT NOT NULL,
  site TEXT NOT NULL,
  gross_annual_eur INTEGER NOT NULL,
  txs TEXT NOT NULL,
  PRIMARY KEY (unit_id, started_at, public_key)
);
